#include <array>
#include <cstddef>
#include <cstdint>
namespace{constexpr int N=64,M=4096;void put(std::uint8_t*out,std::size_t slot,std::int64_t v){auto b=static_cast<std::uint64_t>(v);for(int i=0;i<8;++i)out[slot*8+i]=static_cast<std::uint8_t>(b>>(8*i));}}
extern "C" std::int64_t bidirectional_bfs(const std::int64_t*in,std::size_t len,std::uint8_t*out,std::size_t cap){if(!in||len<4)return -1;auto nv=in[0],av=in[1],sv=in[2],tv=in[3];if(nv<1||nv>N||av<0||av>M||sv<0||sv>=nv||tv<0||tv>=nv||len!=4+2*static_cast<std::size_t>(av))return -1;int n=static_cast<int>(nv);std::array<std::array<bool,N>,N>edge{};std::array<std::array<int,N>,N>adj{};std::array<int,N>deg{};for(int i=0;i<av;++i){auto u=in[4+2*i],v=in[5+2*i];if(u<0||u>=nv||v<0||v>=nv)return -1;if(!edge[u][v]){edge[u][v]=true;adj[u][deg[u]++]=static_cast<int>(v);}}for(int u=0;u<n;++u)for(int v=0;v<n;++v)if(edge[u][v]!=edge[v][u])return -1;int start=static_cast<int>(sv),target=static_cast<int>(tv);std::array<int,N>path{};int pc=0;if(start==target)path[pc++]=start;else{std::array<std::array<bool,N>,2>seen{};std::array<std::array<int,N>,2>parent{};for(auto&r:parent)r.fill(-1);std::array<std::array<int,N>,2>q{};std::array<int,2>head{},tail{};seen[0][start]=seen[1][target]=true;q[0][tail[0]++]=start;q[1][tail[1]++]=target;int meet=-1;while(head[0]<tail[0]&&head[1]<tail[1]&&meet<0){int end=tail[0];for(;head[0]<end;++head[0]){int u=q[0][head[0]];for(int j=0;j<deg[u];++j){int v=adj[u][j];if(seen[0][v])continue;seen[0][v]=true;parent[0][v]=u;q[0][tail[0]++]=v;}}for(int v=0;v<n;++v)if(seen[0][v]&&seen[1][v]){meet=v;break;}if(meet>=0)break;end=tail[1];for(;head[1]<end;++head[1]){int u=q[1][head[1]];for(int j=0;j<deg[u];++j){int v=adj[u][j];if(seen[1][v])continue;seen[1][v]=true;parent[1][v]=u;q[1][tail[1]++]=v;}}for(int v=0;v<n;++v)if(seen[0][v]&&seen[1][v]){meet=v;break;}}if(meet>=0){std::array<int,N>rev{};int k=0;for(int v=meet;v!=-1;v=parent[0][v])rev[k++]=v;while(k>0)path[pc++]=rev[--k];for(int v=parent[1][meet];v!=-1;v=parent[1][v])path[pc++]=v;}}
 auto bytes=static_cast<std::size_t>(1+pc)*8;if(!out||cap<bytes)return -2;put(out,0,pc);for(int i=0;i<pc;++i)put(out,1+i,path[i]);return static_cast<std::int64_t>(bytes);}
